window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cb1f8a1d25f0001b"]={"versions": [{"id": "FIG-cb1f8a1d25f0001b", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Struktur- und Konfigurationsdiagramm (UML-Objekt-/Metamodell-Abstraktion) der AUTOSAR Adaptive Platform (SWS Platform Health Management - PHM).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Mehrfachüberwachung von Checkpoints mittels <em>Alive Supervision</em> innerhalb einer einzelnen <code>SupervisedEntity</code> (<code>SE3</code>) für einen spezifischen Überwachungsmodus (<code>SupervisionMode</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Das PHM realisiert die funktionale Sicherheitsüberwachung (ISO 26262) für Adaptive Applications. Die Alive-Supervision verifiziert zur Laufzeit, ob periodische Funktionen oder Threads innerhalb deterministischer zeitlicher Frequenzkorridore ausgeführt werden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>SupervisedEntity</code> (<code>SE3</code>):</strong></li>\n<li>Logische Gruppierungseinheit für sicherheitsrelevante Ausführungspfade innerhalb eines Prozesses der Adaptive Application.</li>\n<li>Kapselt einen oder mehrere diskrete Überwachungspunkte.</li>\n<li><strong><code>Checkpoint</code> (<code>CP3-1</code>, <code>CP3-2</code>):</strong></li>\n<li>Eindeutig identifizierbare Kontrollpunkte im Applikationscode, die über die Schnittstelle <code>ara::phm::SupervisedEntity::ReportCheckpoint(CheckpointId)</code> getriggert werden.</li>\n<li>Kardinalität: $1 : N$ zwischen <code>SupervisedEntity</code> und <code>Checkpoint</code>.</li>\n<li><strong>Konfigurationsparameter je Checkpoint (Metamodell-Attribute):</strong></li>\n<li><code>ExpectedAliveIndications</code>: Soll-Anzahl der Checkpoint-Meldungen innerhalb eines Bewertungsintervalls.</li>\n<li><code>MinMargin</code>: Maximal zulässige negative Abweichung (Unterschreitung der Soll-Aufrufe).</li>\n<li><code>MaxMargin</code>: Maximal zulässige positive Abweichung (Überschreitung der Soll-Aufrufe).</li>\n<li><code>AliveReferenceCycle</code>: Länge des Referenzüberwachungsfensters (ausgedrückt in Zyklen des PHM-Auswertungstakts).</li>\n<li><code>FailedReferenceCyclesTolerance</code>: Anzahl konsekutiv fehlerhafter Referenzzyklen, bevor ein Zustandstransfer nach <code>ALIVE_FAILED</code> bzw. <code>ALIVE_EXPIRED</code> ausgelöst wird.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Meldungsphase (Asynchron / Event-getrieben):</strong></li>\n<li>Die Applikation durchläuft den Kontrollfluss und meldet das Erreichen von <code>CP3-1</code> bzw. <code>CP3-2</code> via IPC an den PHM-Daemon (<code>ReportCheckpoint</code>).</li>\n<li><strong>Evaluierungsphase (Periodisch / Synchroner PHM-Zyklus):</strong></li>\n<li>Jeder Checkpoint wird unabhängig voneinander nach Ablauf seines jeweiligen <code>AliveReferenceCycle</code> bewertet.</li>\n<li>Gültigkeitsbedingung für einen fehlerfreien Zyklus:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{ExpectedAliveIndications} - \\text{MinMargin} \\le \\text{ActualIndications} \\le \\text{ExpectedAliveIndications} + \\text{MaxMargin}$$</p>\n<ul class=\"fig-list\">\n<li><strong>Fehlerakkumulation & Statusübergang:</strong></li>\n<li>Schlägt ein Zyklus fehl, wird der zyklische Fehlerzähler inkrementiert.</li>\n<li>Überschreitet der Zähler <code>FailedReferenceCyclesTolerance</code>, degradiert der Alive-Status des betroffenen Checkpoints (<code>ALIVE_OK</code> $\\rightarrow$ <code>ALIVE_FAILED</code>).</li>\n<li>Der lokale Zustand der <code>SupervisedEntity</code> wird reevaluiert und fließt in die globale Zustandsmaschine des PHM ein (Auslösung konfigurierter Recovery-Aktionen via State Management / Execution Management).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Unabhängige Parametrierung:</strong></li>\n<li>Mehrere Checkpoints innerhalb derselben <code>SupervisedEntity</code> können disjunkte Ausführungsfrequenzen überwachen (z. B. <code>CP3-1</code> für eine 10-ms-Regelschleife, <code>CP3-2</code> für eine 100-ms-Diagnoseübertragung).</li>\n<li><strong>Jitter & Scheduling-Toleranz:</strong></li>\n<li><code>MinMargin</code> und <code>MaxMargin</code> müssen unter Berücksichtigung von OS-Scheduling-Latenzen, Thread-Präemption und Ausführungs-Jitter gewählt werden, um False Positives zu verhindern.</li>\n<li><strong>Konfigurationsbindung an <code>SupervisionMode</code>:</strong></li>\n<li>Alive-Supervision-Parameter sind an den jeweiligen <code>SupervisionMode</code> gebunden. Bei Moduswechseln können Parametersätze ausgetauscht oder einzelne Checkpoints inaktiv geschaltet werden.</li>\n<li><strong>API-Vertrag:</strong></li>\n<li>Entwickler müssen sicherstellen, dass <code>ReportCheckpoint</code> nicht aus Interrupt-Kontexten mit blockierendem IPC aufgerufen wird und die übergebene <code>CheckpointId</code> exakt der im ARXML-Manifest deklarierten ID entspricht.</li>\n</ul>"}, {"id": "FIG-59c7599c8228d09d", "releases": ["R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Struktur- und Konfigurationsdiagramm (UML-Objekt-/Metamodell-Abstraktion) der AUTOSAR Adaptive Platform (SWS Platform Health Management - PHM).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Mehrfachüberwachung von Checkpoints mittels <em>Alive Supervision</em> innerhalb einer einzelnen <code>SupervisedEntity</code> (<code>SE3</code>) für einen spezifischen Überwachungsmodus (<code>SupervisionMode</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Das PHM realisiert die funktionale Sicherheitsüberwachung (ISO 26262) für Adaptive Applications. Die Alive-Supervision verifiziert zur Laufzeit, ob periodische Funktionen oder Threads innerhalb deterministischer zeitlicher Frequenzkorridore ausgeführt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>SupervisedEntity</code> (<code>SE3</code>):</strong></li>\n<li>Logische Gruppierungseinheit für sicherheitsrelevante Ausführungspfade innerhalb eines Prozesses der Adaptive Application.</li>\n<li>Kapselt einen oder mehrere diskrete Überwachungspunkte.</li>\n<li><strong><code>Checkpoint</code> (<code>CP3-1</code>, <code>CP3-2</code>):</strong></li>\n<li>Eindeutig identifizierbare Kontrollpunkte im Applikationscode, die über die Schnittstelle <code>ara::phm::SupervisedEntity::ReportCheckpoint(CheckpointId)</code> getriggert werden.</li>\n<li>Kardinalität: $1 : N$ zwischen <code>SupervisedEntity</code> und <code>Checkpoint</code>.</li>\n<li><strong>Konfigurationsparameter je Checkpoint (Metamodell-Attribute):</strong></li>\n<li><code>ExpectedAliveIndications</code>: Soll-Anzahl der Checkpoint-Meldungen innerhalb eines Bewertungsintervalls.</li>\n<li><code>MinMargin</code>: Maximal zulässige negative Abweichung (Unterschreitung der Soll-Aufrufe).</li>\n<li><code>MaxMargin</code>: Maximal zulässige positive Abweichung (Überschreitung der Soll-Aufrufe).</li>\n<li><code>AliveReferenceCycle</code>: Länge des Referenzüberwachungsfensters (ausgedrückt in Zyklen des PHM-Auswertungstakts).</li>\n<li><code>FailedReferenceCyclesTolerance</code>: Anzahl konsekutiv fehlerhafter Referenzzyklen, bevor ein Zustandstransfer nach <code>ALIVE_FAILED</code> bzw. <code>ALIVE_EXPIRED</code> ausgelöst wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Meldungsphase (Asynchron / Event-getrieben):</strong></li>\n<li>Die Applikation durchläuft den Kontrollfluss und meldet das Erreichen von <code>CP3-1</code> bzw. <code>CP3-2</code> via IPC an den PHM-Daemon (<code>ReportCheckpoint</code>).</li>\n<li><strong>Evaluierungsphase (Periodisch / Synchroner PHM-Zyklus):</strong></li>\n<li>Jeder Checkpoint wird unabhängig voneinander nach Ablauf seines jeweiligen <code>AliveReferenceCycle</code> bewertet.</li>\n<li>Gültigkeitsbedingung für einen fehlerfreien Zyklus:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{ExpectedAliveIndications} - \\text{MinMargin} \\le \\text{ActualIndications} \\le \\text{ExpectedAliveIndications} + \\text{MaxMargin}$$</p>\n<ul class=\"fig-list\">\n<li><strong>Fehlerakkumulation & Statusübergang:</strong></li>\n<li>Schlägt ein Zyklus fehl, wird der zyklische Fehlerzähler inkrementiert.</li>\n<li>Überschreitet der Zähler <code>FailedReferenceCyclesTolerance</code>, degradiert der Alive-Status des betroffenen Checkpoints (<code>ALIVE_OK</code> $\\rightarrow$ <code>ALIVE_FAILED</code>).</li>\n<li>Der lokale Zustand der <code>SupervisedEntity</code> wird reevaluiert und fließt in die globale Zustandsmaschine des PHM ein (Auslösung konfigurierter Recovery-Aktionen via State Management / Execution Management).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Unabhängige Parametrierung:</strong></li>\n<li>Mehrere Checkpoints innerhalb derselben <code>SupervisedEntity</code> können disjunkte Ausführungsfrequenzen überwachen (z. B. <code>CP3-1</code> für eine 10-ms-Regelschleife, <code>CP3-2</code> für eine 100-ms-Diagnoseübertragung).</li>\n<li><strong>Jitter & Scheduling-Toleranz:</strong></li>\n<li><code>MinMargin</code> und <code>MaxMargin</code> müssen unter Berücksichtigung von OS-Scheduling-Latenzen, Thread-Präemption und Ausführungs-Jitter gewählt werden, um False Positives zu verhindern.</li>\n<li><strong>Konfigurationsbindung an <code>SupervisionMode</code>:</strong></li>\n<li>Alive-Supervision-Parameter sind an den jeweiligen <code>SupervisionMode</code> gebunden. Bei Moduswechseln können Parametersätze ausgetauscht oder einzelne Checkpoints inaktiv geschaltet werden.</li>\n<li><strong>API-Vertrag:</strong></li>\n<li>Entwickler müssen sicherstellen, dass <code>ReportCheckpoint</code> nicht aus Interrupt-Kontexten mit blockierendem IPC aufgerufen wird und die übergebene <code>CheckpointId</code> exakt der im ARXML-Manifest deklarierten ID entspricht.</li>\n</ul>"}], "trans": [{"from": "FIG-cb1f8a1d25f0001b", "to": "FIG-59c7599c8228d09d", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
